interface FormState {
  name: string;
  slug: string;
  summary: string;
  description: string;
  icon: string;
  serviceUrl: string;
  categoryId: string;
  tags: string;
  screenshots: string;
  team: string;
  language: string;
  framework: string;
  version: string;
  supportsMcp: boolean;
  supportsApi: boolean;
  visibility: "public" | "private";
}

const empty: FormState = {
  name: "",
  slug: "",
  summary: "",
  description: "",
  icon: "📦",
  serviceUrl: "",
  categoryId: "",
  tags: "",
  screenshots: "",
  team: "",
  language: "",
  framework: "",
  version: "",
  supportsMcp: false,
  supportsApi: false,
  visibility: "public",
};

export function AppFormPage({ edit = false }: { edit?: boolean }) {
  const { id = "" } = useParams();
  const navigate = useNavigate();
  const client = useQueryClient();
  const categories = useQuery({
    queryKey: ["categories"],
    queryFn: ({ signal }) => api.categories(signal),
  });
  const existing = useQuery({
    queryKey: ["my-app", id],
    // A list without this id means "없음", not a failure: returning undefined
    // would make the query library raise and show its own English message.
    queryFn: async ({ signal }) =>
      (await api.myApps(signal)).find((app) => app.id === id) ?? null,
    enabled: edit,
  });
  const [form, setForm] = useState<FormState>(empty);
  const [complete, setComplete] = useState(false);
  const documents = useGuideDocumentDraft(edit ? id : undefined);
  useEffect(() => {
    if (!existing.data) return;
    setForm({
      name: existing.data.name,
      slug: existing.data.slug,
      summary: existing.data.summary,
      description: existing.data.description ?? "",
      icon: existing.data.icon ?? "📦",
      serviceUrl: existing.data.serviceUrl ?? "",
      categoryId: existing.data.category?.id ?? "",
      tags: existing.data.tags?.join(", ") ?? "",
      screenshots: existing.data.screenshots?.join(", ") ?? "",
      team: existing.data.team ?? "",
      language: existing.data.language ?? "",
      framework: existing.data.framework ?? "",
      version: existing.data.version ?? "",
      supportsMcp: !!existing.data.supportsMcp,
      supportsApi: !!existing.data.supportsApi,
      visibility: existing.data.visibility ?? "public",
    });
  }, [existing.data]);
  const save = useMutation({
    mutationFn: async () => {
      const payload = {
        ...form,
        tags: parseList(form.tags),
        screenshots: parseList(form.screenshots),
      };
      const saved = edit
        ? await api.updateApp(id, payload)
        : await api.createApp(payload);
      // Attachments need the app to exist, so they are applied once it does.
      // A failure here surfaces on the form with the app already saved.
      await documents.apply(saved?.id ?? id);
      return saved;
    },
    onSuccess: async () => {
      setComplete(true);
      await client.invalidateQueries({ queryKey: ["my-apps"] });
    },
  });
  const update = <K extends keyof FormState>(key: K, value: FormState[K]) =>
    setForm((current) => ({ ...current, [key]: value }));
  const submit = (event: FormEvent) => {
    event.preventDefault();
    save.mutate();
  };

  if (edit && existing.isPending)
    return (
      <div className="page">
        <LoadingState />
      </div>
    );
  if (edit && existing.error)
    return (
      <div className="page">
        <ErrorState
          error={existing.error}
          retry={() => void existing.refetch()}
        />
      </div>
    );
  if (edit && !existing.data)
    return (
      <div className="page">
        <EmptyState
          title="앱을 찾을 수 없습니다"
          description="이미 삭제되었거나 내가 등록한 앱이 아닙니다."
          actions={<ButtonLink to="/my/apps">내 앱 목록</ButtonLink>}
        />
      </div>
    );
  if (complete)
    return (
      <div className="page">
        <div className="state-panel">
          <div>
            <div className="state-icon">
              <CheckCircle2 />
            </div>
            <h2>{edit ? "앱이 수정되었습니다" : "앱이 등록되었습니다"}</h2>
            <p>
              승인 Workflow 설정에 따라 즉시 게시되거나 검토 대기 상태가 됩니다.
            </p>
            <div className="state-actions">
              <Button onClick={() => navigate("/my/apps")}>
                내 앱으로 이동
              </Button>
            </div>
          </div>
        </div>
      </div>
    );

  return (
    <div className="page">
      <PageHeader
        eyebrow={edit ? "Edit application" : "Self-service publishing"}
        title={edit ? "앱 수정" : "앱 등록"}
        description="사용자가 실제로 접속할 서비스 URL과 앱 정보를 입력하세요. Git 저장소 정보는 수집하거나 노출하지 않습니다."
      />
      {edit && existing.data && (
        <RejectionNotice app={existing.data} className="mb-5" />
      )}
      <Card className="form-section">
        <form onSubmit={submit}>
          <div className="form-grid">
            <Field label="앱 이름" id="app-name">
              <Input
                id="app-name"
                value={form.name}
                onChange={(event) => update("name", event.target.value)}
                required
                maxLength={100}
              />
            </Field>
            <Field
              label="Slug"
              id="app-slug"
              help="URL에 사용되는 영문 소문자 식별자"
            >
              <Input
                id="app-slug"
                value={form.slug}
                onChange={(event) =>
                  update(
                    "slug",
                    event.target.value
                      .toLowerCase()
                      .replace(/[^a-z0-9-]/g, "-"),
                  )
                }
                required
                pattern="[a-z0-9]+(?:-[a-z0-9]+)*"
              />
            </Field>
            <Field label="한 줄 설명" id="app-summary">
              <Input
                id="app-summary"
                value={form.summary}
                onChange={(event) => update("summary", event.target.value)}
                required
                maxLength={180}
              />
            </Field>
            <Field
