import { Badge } from "../../components/ui";

export const APP_STATUSES = [
  { value: "draft", label: "초안", tone: undefined },
  { value: "pending_review", label: "검토 대기", tone: "warning" },
  { value: "published", label: "게시됨", tone: "positive" },
  { value: "rejected", label: "반려", tone: "danger" },
  { value: "archived", label: "보관됨", tone: undefined },
] as const;

// The one place a stored status turns into words, so a badge and a plain text
// row never name the same status differently.
export function appStatusLabel(status?: string) {
  return (
    APP_STATUSES.find((item) => item.value === status)?.label ?? status ?? "—"
  );
}

export function AppStatusBadge({ status }: { status?: string }) {
  const entry = APP_STATUSES.find((item) => item.value === status);
  return <Badge tone={entry?.tone}>{appStatusLabel(status)}</Badge>;
}

package httpapi

import (
	"net/http"

	"github.com/go-chi/chi/v5"
	"github.com/google/uuid"
	"github.com/hkjang/appstore/internal/model"
)

func (s *Server) createApp(w http.ResponseWriter, r *http.Request) {
	var input model.AppInput
	if err := DecodeJSON(w, r, &input); err != nil {
		WriteError(w, r, err)
		return
	}
	if err := ValidateAppInput(&input); err != nil {
		WriteError(w, r, err)
		return
	}
	principal := CurrentPrincipal(r.Context())
	app, err := s.repository.CreateApp(r.Context(), &principal.User.ID, input, model.AppStatusDraft)
	if err != nil {
		WriteError(w, r, storeError(err, "APP_NOT_FOUND", "앱을 등록할 수 없습니다."))
		return
	}
	// With the security gate on and nothing approved yet, the app is saved as
	// a draft and the owner goes to the security screen; only an unrelated
	// failure is an error.
	result, err := s.submitOrHold(r.Context(), app, principal.User.ID)
	if err != nil {
		WriteError(w, r, submitError(err))
		return
	}
	s.recordAudit(r, "app.create", "app", app.ID.String(), nil, result)
	WriteJSON(w, http.StatusCreated, result.App)
}

func (s *Server) updateApp(w http.ResponseWriter, r *http.Request) {
	id, ok := appIDParam(w, r)
	if !ok {
		return
	}
	before, err := s.repository.GetAppByID(r.Context(), id)
	if err != nil {
		WriteError(w, r, storeError(err, "APP_NOT_FOUND", "앱을 찾을 수 없습니다."))
		return
	}
	principal := CurrentPrincipal(r.Context())
	if (before.OwnerID == nil || *before.OwnerID != principal.User.ID) && !principal.Can("apps:manage") {
		WriteError(w, r, Forbidden("소유한 앱만 수정할 수 있습니다."))
		return
	}
	var input model.AppInput
	if err := DecodeJSON(w, r, &input); err != nil {
		WriteError(w, r, err)
		return
	}
	if err := ValidateAppInput(&input); err != nil {
		WriteError(w, r, err)
		return
	}
	updated, err := s.repository.UpdateApp(r.Context(), id, input)
	if err != nil {
		WriteError(w, r, storeError(err, "APP_NOT_FOUND", "앱을 찾을 수 없습니다."))
		return
	}
	config, configErr := s.repository.GetWorkflowConfig(r.Context())
	if configErr == nil && resubmitAfterEdit(config, before.Status) {
		if result, submitErr := s.submitOrHold(r.Context(), updated, principal.User.ID); submitErr == nil {
			updated = result.App
		} else {
			WriteError(w, r, submitError(submitErr))
			return
		}
	}
	s.recordAudit(r, "app.update", "app", id.String(), before, updated)
	WriteJSON(w, http.StatusOK, updated)
}

func (s *Server) deleteApp(w http.ResponseWriter, r *http.Request) {
	id, ok := appIDParam(w, r)
	if !ok {
		return
	}
	before, err := s.repository.GetAppByID(r.Context(), id)
	if err != nil {
		WriteError(w, r, storeError(err, "APP_NOT_FOUND", "앱을 찾을 수 없습니다."))
		return
	}
	principal := CurrentPrincipal(r.Context())
	if (before.OwnerID == nil || *before.OwnerID != principal.User.ID) && !principal.Can("apps:manage") {
		WriteError(w, r, Forbidden("소유한 앱만 삭제 요청할 수 있습니다."))
		return
	}
	archived, err := s.repository.SetAppStatus(r.Context(), id, "archived")
	if err != nil {
		WriteError(w, r, storeError(err, "APP_NOT_FOUND", "앱을 찾을 수 없습니다."))
		return
	}
	s.recordAudit(r, "app.archive", "app", id.String(), before, archived)
	w.WriteHeader(http.StatusNoContent)
}

// resubmitAfterEdit reports whether editing an app puts it back into the review
// queue. A published app only re-enters when the workflow asks for re-approval,
// but a rejected app has no other way in: updating the app is the only
// submission path an owner has and UpdateApp leaves the status alone, so
// without this a rejected app stays rejected however well the owner fixes what
// the reviewer asked for. A disabled workflow never resubmits, because
// submission then publishes at once and that would push an app a reviewer
// turned down straight into the catalog.
func resubmitAfterEdit(config model.WorkflowConfig, currentStatus string) bool {
	if !config.Enabled {
		return false
	}
	switch currentStatus {
	case model.AppStatusRejected:
		return true
	case model.AppStatusPublished:
		return config.ReapprovalAfterEdit
	default:
		return false
	}
}

func appIDParam(w http.ResponseWriter, r *http.Request) (uuid.UUID, bool) {
	id, err := uuid.Parse(chi.URLParam(r, "app"))
	if err != nil {
		WriteError(w, r, Validation("앱 ID가 올바르지 않습니다.", nil))
		return uuid.Nil, false
	}
	return id, true
}
